import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { apiLayPhongTrong, apiCapNhatThongTin } from '../../api/goi_api';

export default function ThongTinCaNhan() {
    const navigate = useNavigate();

    const [danhSachPhong, setDanhSachPhong] = useState([]);
    const [form, setForm] = useState({
        so_phong: '',
        ho_ten: '',
        so_dien_thoai: ''
    });
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    const user = JSON.parse(localStorage.getItem('user') || '{}');

    useEffect(() => {
        const fetchPhongTrong = async () => {
            try {
                setLoading(true);
                const data = await apiLayPhongTrong();
                setDanhSachPhong(data || []);
            } catch (error) {
                console.error('Lỗi lấy danh sách phòng trống:', error);
                alert('Không thể tải danh sách phòng trống!');
            } finally {
                setLoading(false);
            }
        };

        fetchPhongTrong();
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setForm((prev) => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSave = async () => {
        if (!user?.id) {
            return alert('Không tìm thấy tài khoản đăng nhập!');
        }

        if (!form.so_phong || !form.ho_ten.trim() || !form.so_dien_thoai.trim()) {
            return alert('Vui lòng nhập đầy đủ thông tin!');
        }

        try {
            setSaving(true);

            const data = await apiCapNhatThongTin({
                id: user.id,
                so_phong: form.so_phong,
                ho_ten: form.ho_ten.trim(),
                so_dien_thoai: form.so_dien_thoai.trim()
            });

            const newUser = {
                ...user,
                so_phong: data.user.so_phong,
                ho_ten: data.user.ho_ten,
                so_dien_thoai: data.user.so_dien_thoai,
                da_khai_bao: 1
            };

            localStorage.setItem('user', JSON.stringify(newUser));

            alert('Lưu thông tin thành công!');
            navigate('/dashboard-cu-dan/thong-bao');
        } catch (error) {
            console.error('Lỗi cập nhật thông tin:', error);
            const msg = error.response?.data?.message || 'Lưu thông tin thất bại!';
            alert(msg);
        } finally {
            setSaving(false);
        }
    };

    return (
        <div style={containerStyle}>
            <div style={cardStyle}>
                <h2 style={titleStyle}>CẬP NHẬT THÔNG TIN</h2>

                <label style={labelStyle}>Mã căn hộ:</label>
                {loading ? (
                    <div style={inputStyle}>Đang tải danh sách phòng...</div>
                ) : (
                    <select
                        name="so_phong"
                        value={form.so_phong}
                        onChange={handleChange}
                        style={inputStyle}
                    >
                        <option value="">-- Chọn phòng --</option>
                        {danhSachPhong.map((item) => (
                            <option key={item.ma_phong} value={item.ma_phong}>
                                {item.ma_phong}
                            </option>
                        ))}
                    </select>
                )}

                <label style={labelStyle}>Họ và tên:</label>
                <input
                    type="text"
                    name="ho_ten"
                    placeholder="Nhập tên cư dân..."
                    value={form.ho_ten}
                    onChange={handleChange}
                    style={inputStyle}
                />

                <label style={labelStyle}>Số điện thoại:</label>
                <input
                    type="text"
                    name="so_dien_thoai"
                    placeholder="Ví dụ: 0905123456"
                    value={form.so_dien_thoai}
                    onChange={handleChange}
                    style={inputStyle}
                />

                <button
                    onClick={handleSave}
                    disabled={saving}
                    style={{
                        ...buttonStyle,
                        opacity: saving ? 0.6 : 1,
                        cursor: saving ? 'not-allowed' : 'pointer'
                    }}
                >
                    {saving ? 'Đang lưu...' : 'XÁC NHẬN LƯU'}
                </button>
            </div>
        </div>
    );
}

const containerStyle = {
    flex: 1,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%'
};

const cardStyle = {
    width: '100%',
    maxWidth: '560px',
    background: 'rgba(255,255,255,0.95)',
    borderRadius: '25px',
    padding: '30px',
    display: 'flex',
    flexDirection: 'column',
    gap: '12px'
};

const titleStyle = {
    textAlign: 'center',
    color: '#8b5e5e',
    marginBottom: '10px'
};

const labelStyle = {
    fontWeight: 'bold',
    color: '#444'
};

const inputStyle = {
    padding: '14px',
    borderRadius: '12px',
    border: '1px solid #ddd',
    outline: 'none',
    fontSize: '15px'
};

const buttonStyle = {
    marginTop: '12px',
    padding: '14px',
    border: 'none',
    borderRadius: '12px',
    backgroundColor: '#9b6b6b',
    color: '#fff',
    fontWeight: 'bold',
    fontSize: '16px'
};
